<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Offer\Action\Query;

use Module\Offer\Action\Dto\Admin\StoreDto;
use Module\Offer\Action\Query\AdminGetListFiltersQry;
use Module\Store\Action\Query\GetStoreListQry;
use Module\Store\Model\Store;
use Module\Store\Model\StoreRepository;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class AdminGetListFiltersQryTest extends IntegrationTestCase
{
    private AdminGetListFiltersQry $sut;

    private StoreRepository $storeRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->storeRepository = $this->container->get(StoreRepository::class);

        $this->sut = new AdminGetListFiltersQry(
            $this->container->get(GetStoreListQry::class)
        );
        $this->prepareDb();
    }

    #[Test]
    public function handleReturnsMappedStoresOrderedByName(): void
    {
        $result = $this->sut->handle();

        $this->assertEquals(
            [
                new StoreDto(storeId: 21, storeName: 'Alpha Store'),
                new StoreDto(storeId: 22, storeName: 'Beta Store'),
                new StoreDto(storeId: 20, storeName: 'Gamma Store'),
            ],
            $result->stores,
        );
    }

    private function prepareDb(): void
    {
        $this->storeRepository->saveWithId(Store::factory('STR-20', 'Gamma Store', 'Gamma Address', 20));
        $this->storeRepository->saveWithId(Store::factory('STR-21', 'Alpha Store', 'Alpha Address', 21));
        $this->storeRepository->saveWithId(Store::factory('STR-22', 'Beta Store', 'Beta Address', 22));
        $this->storeRepository->flush();
    }
}
